query HomeQuery {
  ...LayoutFragment
  homePages: pages(first: 100) {
    nodes {
      id
      title
      slug
      excerpt
      status
    }
  }
  latestPosts: posts(first: 100) {
    nodes {
      id
      title
      slug
      excerpt
      status
      publishedAt
    }
  }
  pageBySlug(slug: "home") {
    id
    title
    slug
    content
    excerpt
    status
    publishedAt
    createdAt
    updatedAt
  }
}

fragment LayoutFragment on RootQuery {
  viewer {
    id
    displayName
    role
  }
  navigationPages: pages(first: 100) {
    nodes {
      id
      title
      slug
      status
    }
  }
  navigationPosts: posts(first: 100) {
    nodes {
      status
      id
    }
  }
  navigationProducts: products(first: 100) {
    nodes {
      status
      id
    }
  }
}

